import socket
import time

class Worm:
    def __init__(self, hostname, port, message="Hello from the Worm!"):
        self.hostname = hostname
        self.port = port
        self.message = message
        self.alive = True  # Initialize as alive
        self.infected = False # Flag to track whether the worm is infecting others

    def connect(self, host, port):
        try:
            self.sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.sock.connect((host, port))
            print(f"{self.hostname} connected to {host}:{port}")
        except socket.error:
            print(f"{self.hostname} could not connect to {host}:{port}")
            self.alive = False

    def send_message(self):
        if self.alive:
            self.sock.sendall(self.message.encode())
            print(f"{self.hostname} sent message: {self.message}")

    def receive_message(self):
        if self.alive:
            data = self.sock.recv(1024).decode()
            if data:
                print(f"{self.hostname} received message: {data}")

    def update_infection(self):
        if self.alive:
            self.infected = True  
            print(f"{self.hostname} is infected!")
        else:
            print(f"{self.hostname} is not alive, cannot infect other computers")


def main():
    # Customize network parameters
    hostname = "your_hostname"
    port = 1234  
    worm = Worm(hostname, port)

    # Connect to the designated server
    worm.connect(hostname, port)

    # Send a message
    worm.send_message()

    # Receive a message (assuming a server is expecting a message)
    worm.receive_message()

    # Infect other computers if alive
    if worm.alive:
        worm.update_infection()

if __name__ == "__main__":
    main()
